measures.Expression:
CALCULATE(
    [Total Consultas], 
    SAMEPERIODLASTYEAR(
        DATESBETWEEN(
            'Calendario'[Date],
            MIN('Calendario'[Date]),
            MAX('Calendario'[Date])
        )
    )
)

